async function patchAllRounds() {
  const client = await pool.connect();
  try {
    const rounds = Object.keys(ROUND_STATS).map(Number);
    console.log(`🔍 Patching rounds: ${rounds.join(", ")}`);

    const result = await client.query(
      `SELECT id, season, game_type, round, picks
       FROM selections
       WHERE season = 2026 AND round = ANY($1)
       ORDER BY round, game_type`,
      [rounds]
    );

    console.log(`Found ${result.rows.length} rows to patch\n`);

    if (result.rows.length === 0) {
      console.log("⚠️  No rows found. Check that selections exist for these rounds.");
      return;
    }

    let totalUpdated = 0, totalPatched = 0, totalNotFound = 0;

    for (const row of result.rows) {
      const statsForRound = ROUND_STATS[row.round];
      if (!statsForRound) continue;

      const picks = Array.isArray(row.picks) ? row.picks : [];
      let rowPatched = false, pickCount = 0, notFound = 0;

      const patchedPicks = picks.map((punterRow) => {
        if (!Array.isArray(punterRow)) return punterRow;
        return punterRow.map((pick) => {
          const pid = pick?.playerId;
          if (!pid) return pick;
          const stats = statsForRound[pid];
          if (stats) {
            rowPatched = true;
            pickCount++;
            return { ...pick, stats };
          }
          notFound++;
          return pick;
        });
      });

      totalPatched += pickCount;
      totalNotFound += notFound;

      if (rowPatched) {
        await client.query(
          `UPDATE selections SET picks = $1::jsonb, updated_at = NOW() WHERE id = $2`,
          [JSON.stringify(patchedPicks), row.id]
        );
        totalUpdated++;
        console.log(
          `  ✅ Round ${String(row.round).padStart(1)} | ${row.game_type.padEnd(20)} | ${pickCount} picks patched, ${notFound} not found`
        );
      } else {
        console.log(
          `  ℹ️  Round ${String(row.round).padStart(1)} | ${row.game_type.padEnd(20)} | no matching players`
        );
      }
    }

    console.log(`\n✅ Patch complete!`);
    console.log(`   Rows updated:    ${totalUpdated}`);
    console.log(`   Picks patched:   ${totalPatched}`);
    console.log(`   Not found:       ${totalNotFound} (rookies/emergencies not in roster — expected)`);

  } catch (err) {
    console.error("💥 Error:", err);
    throw err;
  } finally {
    client.release();
    await pool.end();
  }
}

patchAllRounds().catch(err => { console.error(err); process.exit(1); });